entries[205682] = { ["name"] = "Großer Schattenflammenrestesack", ["text"] = "Wird beim Aufheben gebunden\n\"Ein unaufhörlich schwelender Beutel, der einst mit den Rückständen von Fyrakks Schattenflamme gestärkt wurde. Es bleibt nichts Brauchbares übrig.\"\nVerkaufspreis:" }
entries[205684] = { ["name"] = "Verbotene Flunder", ["text"] = "Benutzen: Nehmt einen mutigen Bissen und verliert im Verlauf von 20 Sek. 332.5% Eurer maximalen Gesundheit. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr beim Essen mindestens 10 Sek. überlebt, erleidet Ihr qualvolle Schmerzen, wodurch alle Sekundärwerte 1 Stunde lang um 15 verringert werden.\n\"Dieser Fisch ist schon tausende Jahre in Lava eingelegt und deswegen AUF KEINEN FALL essbar. Und trotzdem...\"\nVerkaufspreis:" }
entries[205686] = { ["name"] = "Klickende Schere", ["text"] = "Benutzen: Klickt drei Mal mit der Schere und verwandelt Euch 10 Min. lang in einen Urmakrura." }
entries[205688] = { ["name"] = "Klebriger Glitzerschuppenklumpen", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Schleudert einen Klumpen Glitzerschuppenglitzer auf Euer Ziel. Aber Vorsicht, das Zeug kommt überall hin... (10 Min Abklingzeit)" }
entries[205689] = { ["name"] = "Feldherrenkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Dieser elementerfüllte Brocken ist ein Zeichen Eures Könnens und kann den Schatz öffnen!\"" }
entries[205690] = { ["name"] = "Tauschschmaus", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Das perfekte Mahl nach einem guten Tauschgeschäft.\"\nVerkaufspreis:" }
entries[205691] = { ["name"] = "Hypnotisierender Murlocköder", ["text"] = "\"Schaut ihn Euch lieber nicht zu lange an.\"\nVerkaufspreis:" }
entries[205692] = { ["name"] = "Stellaviatorisuppe", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Schickt Euch auf eine Entdeckungsmission.\"\nVerkaufspreis:" }
entries[205693] = { ["name"] = "Gitterstinkmorchel", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 70313 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Was habt Ihr erwartet?\"\nVerkaufspreis:" }
