entries[205793] = { ["name"] = "Flattersouffliege", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 70313 / 5 * 20) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Aus importierten Flatterlibellen.\"\nVerkaufspreis:" }
