entries[205795] = { ["name"] = "Sich windender Wurm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Ein vergleichsweise fetter Wurm, der sich in Eurer Hand windet.\"" }
entries[205796] = { ["name"] = "Geschmolzenes Lavabündel", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Legt das Bündel an, wodurch Ihr schnell abkühlende Lava auf Eure \"Freunde\" werfen könnt. Tut zwar nicht weh, ist aber trotzdem ziemlich heiß! (30 Min Abklingzeit)" }
entries[205797] = { ["name"] = "Schmutziges Bündel", ["text"] = "Questgegenstand\n\"Es ist ekelhaft und durch Versteinerung verschlossen, doch vielleicht befindet sich etwas Interessantes darin.\"" }
entries[205798] = { ["name"] = "Schulterstücke des Onyxtiegels", ["text"] = "Wird beim Aufheben gebunden\nSchulter Platte\n1069 Rüstung\n+353 [Stärke oder Intelligenz]\n+1.082 Ausdauer\nErhöht Eure Tempowertung um + 190.\nErhöht Eure Meisterschaftswertung um + 375.\nHaltbarkeit 100 / 100\nKlassen: Krieger\nEisen des Onyxtiegels (0/5)\nKriegsbrustpanzer des Onyxtiegels\nHandschützer des Onyxtiegels\nThraexhelm des Onyxtiegels\nBeinplatten des Onyxtiegels\nSchulterstücke des Onyxtiegels\n(2) Set Waffen: 'Tiefe Wunden' erhöht Eure kritische Trefferchance und den an betroffenen Zielen verursachten kritischen Schaden um 5%.\n(2) Set Furor: Erhöht den Schaden und die kritische Trefferchance von 'Toben' um 15%.\n(2) Set Schutz: 'Schildschlag' verursacht 15% mehr Schaden und verringert die Abklingzeit von 'Letztes Gefecht' um 2 Sek. Während 'Letztes Gefecht' sind diese Effekte verdoppelt.\n(4) Set Waffen: Bei kritischen Treffern durch 'Tiefe Wunden' besteht eine Chance, dass der Schaden Eures nächsten Einsatzes von 'Tödlicher Stoß' um 10% erhöht wird und dieser Einsatz Gegnern vor Euch [(19.32% der Angriffskraft) * 2] körperlichen Schaden zufügt. Bis zu 3-mal stapelbar. Der Schaden ist bei über 5 Zielen verringert. (2s Abklingzeit)\n(4) Set Furor: 'Toben' bewirkt, dass Euer nächster 'Blutdurst' eine um 12% erhöhte kritische Trefferchance hat, 35% mehr Schaden verursacht und 2 zusätzliche Wut erzeugt. Bis zu 10-mal stapelbar.\n(4) Set Schutz: Für 20 Sek. nachdem 'Letztes Gefecht' endet, entfesselt 'Schildschlag' eine Kraftwelle, die Gegnern vor Euch (135% der Angriffskraft) körperlichen Schaden zufügt und ihren Euch zugefügten Schaden 5 Sek. lang um 5% verringert.\nVerkaufspreis:" }
