entries[205900] = { ["name"] = "Schimmernder drakonischer Edelstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Ein schimmernder Rubin sitzt in einer schönen goldenen Fassung drakonischen Ursprungs. Vielleicht hat jemand in Loamm Interesse daran?\"" }
entries[205901] = { ["name"] = "Knuspriger Käfer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Die glänzend rote Farbe des Panzers dieses Käfers, erweckt Vorstellungen von Äpfeln und Kirschen.\"" }
entries[205902] = { ["name"] = "Tiefenschinderklaue", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Diese Kristallklaue ist rasiermesserscharf!\"" }
entries[205903] = { ["name"] = "Tauschkiesel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft einen Kieselbrocken weg.\n\"Die Überreste einer zerbrochenen Tauschmarke. Kann in Loamm in der Zaralekhöhle gegen Waren eingetauscht oder für ein Silber verkauft werden.\"\nVerkaufspreis:" }
entries[205904] = { ["name"] = "Leuchtende klickende Schere", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Klickt drei Mal mit der Schere und verwandelt Euch 10 Min. lang in einen Urmakrura." }
entries[205906] = { ["name"] = "Gefiederter Freund", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Dieses Entenplüschtier ist stark abgenutzt. Sein früherer Besitzer hat es offensichtlich sehr geliebt.\"" }
entries[205907] = { ["name"] = "Durchnässtes Totem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Diese merkwürdige Statuette ist komplett durchnässt, als wäre sie gerade erst unter Wasser getunkt worden. Sie gibt auch einen strengen fischigen Geruch von sich.\"" }
entries[205908] = { ["name"] = "Vererbte Weisheit von Senegos", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Ein Teil der Weisheit des uralten blauen Drachen, überliefert in einer Form, die er sicherlich für amüsant hielt. Denkt an eine Ja-Nein-Frage und lasst Euch davon leiten. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[205909] = { ["name"] = "Gespanntes Segeltuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Ein schönes Stück gespannten Segeltuchs. Könnte für eine Trommel oder als Leinwand für ein Geruchsgemälde verwendet werden.\"" }
entries[205910] = { ["name"] = "Blubberndes Elixier", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Die Flüssigkeit in diesem verzierten Behälter riecht nach Blaubeeren und Meerwasser. Sie blubbert so stark, dass es fast schon wie ein Zischen klingt.\"" }
entries[205911] = { ["name"] = "Mysteriöses Räucherwerk", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Das ist definitiv Räucherwerk, doch es riecht komplett anders als das aus Loamm!\"" }
entries[205912] = { ["name"] = "Lederumhüllte Flasche", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Es riecht, als wäre die Flasche leer, doch feine Geruchsnoten eines herben Getränks sind noch zu wahrzunehmen.\"" }
entries[205913] = { ["name"] = "Leeres Notizbuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Ein recht großes, leeres Buch (nach Niffenstandard).\"" }
