entries[205933] = { ["name"] = "Schlüsselsteinaffix hinzufügen: Umschlingend", ["text"] = "Dauer: 12 std. (Realzeit)\nBenutzen: Fügt einem mythischen Schlüsselstein das Affix Umschlingend hinzu.\nVerkaufspreis:" }
