entries[205936] = { ["name"] = "Neues Tonikum Niffen-Schnüffel-Ex", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Das neue Tonikum Niffen-Schnüffel-Ex blockiert sämtliche von den Nasen anderer Leute produzierten Geräusche - garantiert! Nützlich für alle, die kein Niffengeschnüffel (oder generell kein Geschnüffel) mehr hören möchten.\n\nACHTUNG: Blockiert ausschließlich Geräusche, keine Gerüche. (5 Sek. Abklingzeit)\n\"Da muss man nicht die Nase rümpfen!\"" }
entries[205937] = { ["name"] = "Posti", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[205938] = { ["name"] = "Erhitzter Titanenschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Mit diesem Schlüssel könnt Ihr endlich den Schatz öffnen!\"" }
entries[205939] = { ["name"] = "Eiserner Titanenschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Mit diesem Schlüssel könnt Ihr endlich den Schatz öffnen!\"" }
