entries[205954] = { ["name"] = "Dreidimensionaler Kompass", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Rekonfiguriert Euren Wyrmlochgenerator, damit er Euch in die Zaralekhöhle teleportieren kann. Manchmal sorgen selbst die einfachsten Dinge für einen Geistesblitz!\nBenötigt Ingenieurskunst der Dracheninseln (1)\n\"Die meisten Kompasse zeigen nach Norden, dieser hier zeigt hingegen nach unten. Nützlich für alle, die der Schwerkraft nicht trauen.\"\nVerkaufspreis:" }
entries[205955] = { ["name"] = "Azurblauer Erneuerungsmantel", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nSchulter Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[205956] = { ["name"] = "Azurblaues Erneuerungscape", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[205957] = { ["name"] = "Azurblauer Erneuerungswappenrock", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nWappenrock\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[205958] = { ["name"] = "Ensemble: Azurblauer Erneuerungsaufputz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des azurblauen Erneuerungsaufputzsets.\n\"Ein klassischer drakonischer Aufputz, vom blauen Drachenschwarm eigens für Euch als Dank für Eure Hilfe herbeibeschworen.\"\nVerkaufspreis:" }
entries[205959] = { ["name"] = "Brief von Kirygosa", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lest den Brief.\n\"Ein einziges Stück dickes Pergament, das mit Bindfaden zusammengebunden ist.\"" }
entries[205962] = { ["name"] = "Nachhallender Sturm-Flugstein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Enthält 10 Flugsteine." }
entries[205963] = { ["name"] = "Schnüffelsalze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Bringt einen Freund dazu, Euch zu besuchen! (1 Stunde Abklingzeit)\nBenötigt Ruhmrang 11 bei den Niffen von Loamm.\n\"Riecht das!\"\nVerkaufspreis:" }
entries[205964] = { ["name"] = "Kleines Vorratspaket von Loamm", ["text"] = "Wird beim Aufheben gebunden\n\"Beinhaltet Vorräte der Dracheninseln, die gegen Fraktionsgegenstände eingetauscht oder zur Förderung von Fertigkeiten für Fraktionstätigkeiten eingesetzt werden können.\"\n<Zum Öffnen rechtsklicken>" }
entries[205965] = { ["name"] = "Großes Vorratspaket von Loamm", ["text"] = "Wird beim Aufheben gebunden\n\"Beinhaltet Vorräte der Dracheninseln, die gegen Fraktionsgegenstände eingetauscht oder zur Förderung von Fertigkeiten für Fraktionstätigkeiten eingesetzt werden können.\"\n<Zum Öffnen rechtsklicken>" }
