entries[205968] = { ["name"] = "Übervolles Vorratspaket von Loamm", ["text"] = "Wird beim Aufheben gebunden\n\"Beinhaltet Vorräte der Dracheninseln, die gegen Fraktionsgegenstände eingetauscht oder zur Förderung von Fertigkeiten für Fraktionstätigkeiten eingesetzt werden können.\"\n<Zum Öffnen rechtsklicken>" }
entries[205969] = { ["name"] = "Leuchtender Schlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Verströmt ein zartes arkanes Leuchten.\"" }
entries[205970] = { ["name"] = "Azur-Flugstein", ["text"] = "Wird beim Aufheben gebunden\n\"Einst enthielt er die Macht der Flugsteine. Jetzt ist es ein schöner Briefbeschwerer.\"\nVerkaufspreis:" }
entries[205971] = { ["name"] = "Steinzertrümmernder Ausgräber", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Axt\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 25 / 25\nBenötigt Ruhmrang 18 bei den Niffen von Loamm.\n\"Grundgestein ist dieser Spitzhacke nicht gewachsen.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[205972] = { ["name"] = "Dekoratives Niffenschwert", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Schwert\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 25 / 25\nBenötigt Ruhmrang 18 bei den Niffen von Loamm.\n\"Wenig überraschend wurde diese Schaufel nicht von den Niffen hergestellt.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
