entries[205978] = { ["name"] = "Klumpen Schleim aus Azmerloth", ["text"] = "Wird beim Aufheben gebunden\n\"Wenn Ihr ein Murloc seid, riecht das hier nach zu Hause.\"" }
entries[205980] = { ["name"] = "Schneckenlasso", ["text"] = "Questgegenstand\nBenutzen: Wirft ein Lasso nach einer Schnecke, um sie zu bändigen und ihren Schleim einzusammeln.\n\"Werft dieses Lasso, um die am besten riechenden Schnecken einzufangen, die Zaralek zu bieten hat.\"" }
