entries[205982] = { ["name"] = "Verlorene Grabungskarte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gebt Myrrit die Karte, damit er Euch auf eine andere Ausgrabung begleiten kann.\n\nMuss in Loamm in der Nähe von Myrrit benutzt werden. Myrrit kann bis zu 3 Karten gleichzeitig haben.\nVerkaufspreis:" }
entries[205983] = { ["name"] = "Echt dufter Niffenschatz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Enthält die besten (und geruchsintensivsten!) Geschenke, die die Niffen für ihre Freunde haben.\"\n<Zum Öffnen rechtsklicken>" }
entries[205984] = { ["name"] = "Getauschte Ausgrabungskarte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gebt Myrrit die Karte, damit er Euch auf eine andere Ausgrabung begleiten kann.\n\nMuss in Loamm in der Nähe von Myrrit benutzt werden. Myrrit kann bis zu 3 Karten gleichzeitig haben.\nVerkaufspreis:" }
entries[205985] = { ["name"] = "Insigne der Niffen von Loamm", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Gewährt 500 Ruf bei den Niffen von Loamm. (2 Sek. Abklingzeit)" }
entries[205986] = { ["name"] = "Abgenutzter Brennofen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Schmiedekunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Schmiedekunst der Dracheninseln (25)\n\"Ein Brennofen, der eines Flammenmeisters würdig ist.\"" }
entries[205987] = { ["name"] = "Schwefel-Rettungsring", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Schmiedekunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Schmiedekunst der Dracheninseln (25)\n\"Selbst Drachkin brauchen manchmal ein bisschen Hilfe.\"" }
entries[205988] = { ["name"] = "Ältestenspeer der Zaqali", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Schmiedekunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Schmiedekunst der Dracheninseln (25)\n\"Ein mächtiger Speer, der von einem Zaqali-Schmiedekunstmeister erschaffen wurde.\"" }
entries[205989] = { ["name"] = "Symbol der Freundschaft", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 2500 Ruf bei den Niffen von Loamm.\n\"Je mehr die Niffen Euch mögen, desto besser riecht es.\"\nVerkaufspreis:" }
entries[205990] = { ["name"] = "Wilder Schlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Mit diesem Schlüssel könnt Ihr endlich den Schatz öffnen!\"" }
entries[205991] = { ["name"] = "Glänzendes Zeichen der Dankbarkeit", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 2500 Ruf bei den Niffen von Loamm.\n\"Von Tubberos in einer Höhle nahe Nal ks'kol gefunden. Es war ihm wichtig, dass Ihr das erhaltet.\"\nVerkaufspreis:" }
entries[205992] = { ["name"] = "Hochgewürgter Halbverdauter Fisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 2500 Ruf bei den Niffen von Loamm.\n\"Von einem Kriecherdrachen vor Eure Füße geworfen.\"\nVerkaufspreis:" }
entries[205993] = { ["name"] = "Schlüsselsteinkarte festlegen: Der Vortexgipfel", ["text"] = "Benutzen: Legt den Vortexgipfel als Dungeon für einen mythischen Schlüsselstein fest.\nVerkaufspreis:" }
entries[205994] = { ["name"] = "Foliant des Erdwächters", ["text"] = "Questgegenstand\n\"Ein Foliant, der auf dem normalen Schwierigkeitsgrad aus Neltharions Sanktum in Aberrus, Schmelztiegel der Schatten geholt wurde.\"" }
entries[205996] = { ["name"] = "Foliant des Erdwächters", ["text"] = "Questgegenstand\n\"Ein Foliant, der auf dem heroischen Schwierigkeitsgrad aus Neltharions Sanktum in Aberrus, Schmelztiegel der Schatten geholt wurde.\"" }
entries[205997] = { ["name"] = "Foliant des Erdwächters", ["text"] = "Questgegenstand\n\"Ein Foliant, der auf dem mythischen Schwierigkeitsgrad aus Neltharions Sanktum in Aberrus, Schmelztiegel der Schatten geholt wurde.\"" }
entries[205998] = { ["name"] = "Zeichen des Respekts", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 2500 Ruf bei den Niffen von Loamm.\n\"Ein Symbol des Respekts dafür, dass Ihr für die Dracheninseln und ihre Bewohner Euer Leben aufs Spiel setzt.\"\nVerkaufspreis:" }
entries[205999] = { ["name"] = "Vulkanischer Bildhauer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt einem Gegenstand der Saison 2 von Dragonflight, der noch keinen Sockel besitzt, einen hinzu. Kann auf Helme, Halsketten, Armschienen, Gürtel und Ringe angewandt werden." }
entries[206000] = { ["name"] = "Frostfeuerschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Glühend heiß, aber trotzdem mit einer dünnen Eisschicht überzogen.\"" }
entries[206001] = { ["name"] = "Frostumhülltes Schlüsselfragment", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert ein flammenumhülltes Schlüsselfragment und ein frostumhülltes Schlüsselfragmente, um einen Frostfeuerschlüssel zu erschaffen.\n\"Gefrierend kalt.\"" }
entries[206002] = { ["name"] = "Flammenumhülltes Schlüsselfragment", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert ein flammenumhülltes Schlüsselfragment und ein frostumhülltes Schlüsselfragmente, um einen Frostfeuerschlüssel zu erschaffen.\n\"Raucht vor innerer Hitze.\"" }
entries[206003] = { ["name"] = "Horadrischer Brotbeutel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n36 Platz Tasche\n\"Da könnte ein großes Lager drin sein!\"" }
entries[206004] = { ["name"] = "Umhang der Feindschaft", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\n1 Rüstung\n\"Dieses Objekt verströmt Wellen des Hasses.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206005] = { ["name"] = "Wirts kämpferisches Bein", ["text"] = "Kosmetisch\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 20 / 20\n\"Wer ist Wirt?\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206006] = { ["name"] = "Dank des Erdwächters", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 2500 Ruf bei den Niffen von Loamm.\n\"Eine Blume, aus der Erde gewachsen, die der Erdwächter zu beschützen schwor, und ein Geschenk an Euch für Euer Heldentum.\"\nVerkaufspreis:" }
entries[206007] = { ["name"] = "Schatzschnapptasche", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\n1 Rüstung\n\"Wie haben die all diese Schätze hier reinbekommen?\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206008] = { ["name"] = "Alptraumbanner", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Stellt das Alptraumbanner auf. (3 Min Abklingzeit)\n\"Es ist das Banner, von dem Ihr immer geträumt habt. In Euren Alpträumen.\"" }
entries[206009] = { ["name"] = "Ouroboros-Tafel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert die Ouroborostafel mit fleischlichen Entwürfen.\n\"Komplexe Diagramme bedecken die Oberfläche, und vier Zeichnungen erstrecken sich über die Ränder des Steins hinaus. Ein beeindruckender Ouroboros befindet sich in der Mitte.\"" }
entries[206010] = { ["name"] = "Entwürfe des Fleisches", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert die Ouroborostafel mit fleischlichen Entwürfen.\n\"Dekoriert mit uralten Symbolen von Blut und Wasser.\"" }
entries[206011] = { ["name"] = "Entwürfe der Knochen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert die Ouroborostafel mit Knochenentwürfen.\n\"Dekoriert mit uralten Symbolen von Knochen und Erde.\"" }
entries[206012] = { ["name"] = "Entwürfe des Geistes", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert die Ouroborostafel mit Geistesentwürfen.\n\"Dekoriert mit uralten Symbolen von Geist und Feuer.\"" }
entries[206013] = { ["name"] = "Entwürfe der Seele", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert die Ouroborostafel mit Seelenentwürfen.\n\"Dekoriert mit uralten Symbolen von Seele und Luft.\"" }
entries[206014] = { ["name"] = "Ouroboros-Tafel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert die Ouroborostafel mit Knochenentwürfen.\n\"Kreisförmige Zeichnungen zeigen ein großes Spiralmuster, das auf der linken Seite beginnt. Symbole von Wasser und Blut fließen in dieses und die fehlenden Bereiche am unteren Ende.\"" }
entries[206015] = { ["name"] = "Ouroboros-Tafel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert die Ouroborostafel mit Geistesentwürfen.\n\"Symbole von Knochen und Erde säumen den Weg der Spirale, die sich von unten zur fehlenden rechten Seite windet.\"" }
entries[206016] = { ["name"] = "Ouroboros-Tafel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert die Ouroborostafel mit Seelenentwürfen.\n\"Symbole von Geist und Feuer winden sich um die geschnitzte Spirale, bewegen sich nach innen und oben, bis sie die Spitze erreichen.\"" }
entries[206017] = { ["name"] = "Ouroboros-Tafel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert die Ouroborostafel mit Kob'roks leuchtender Schuppe.\n\"Sorgfältig gezeichnete Symbole von Seele und Luft zieren die Spitze, von wo sich die Spirale sich nach innen windet. Der Ouroboros in der Mitte strahlt hell, während violette Energie durch die Spirale und in die Mitte gesogen wird.\"" }
entries[206018] = { ["name"] = "Baa'lial-Seelenstein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Baa'l beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[206019] = { ["name"] = "Zurückgelassener Reservefallschirm", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Schneidereiwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Schneiderei der Dracheninseln (25)\n\"Da hatte jemand Glück, es ist nur der Reservefallschirm. Von der Nadelarbeit könnt Ihr viel lernen!\"" }
entries[206020] = { ["name"] = "Kapuze der Feindschaft", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Dieses Objekt verströmt Wellen des Hasses.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206021] = { ["name"] = "Kob'roks leuchtende Schuppe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kombiniert die Ouroborostafel mit Kob'roks leuchtender Schuppe.\n\"Ein angemessenes Opfer.\"" }
entries[206022] = { ["name"] = "Anduins Glücks-Hearthstone-Karte", ["text"] = "Questgegenstand\n\"Eine alt aussehende gewöhnliche Karte mit leicht zerfledderten Rändern, die eine Wache von Sturmwind darstellt.\"" }
entries[206025] = { ["name"] = "Medizinisches Verbandsset benutzen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Schneidereiwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Schneiderei der Dracheninseln (25)\n\"Die meisten Vorräte wurden verbraucht, aber einige Verbände sind übrig.\"" }
entries[206027] = { ["name"] = "Zügel des Teufelskristallskorpions", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren Teufelskristallskorpion oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das Ergebnis eines Teufelsinfusionsexperiments an einem Nachkommen von Skorpyron.\"\nHandelsposten" }
entries[206028] = { ["name"] = "Truhe voller Gold", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält 1.000 Gold.\"\n<Zum Öffnen rechtsklicken>" }
entries[206030] = { ["name"] = "Fein besticktes Banner", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Schneidereiwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Schneiderei der Dracheninseln (25)\n\"Die Qualität dieses Banners ist schlicht atemberaubend. Es wurde von einem begabten Kunsthandwerker erschaffen.\"" }
entries[206031] = { ["name"] = "Aufwendige Zaqali-Runen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Inschriftenkundewissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Inschriftenkunde der Dracheninseln (25)\n\"Uralte Magie geht von den in die Oberfläche geschnitzten Runen aus.\"" }
entries[206033] = { ["name"] = "Unübersetzter Obsidian-Foliant", ["text"] = "Wird beim Aufheben gebunden\n\"Ein unübersetzter Foliant, den Furorion in der Obsidianzitadelle fand. Er schenkte ihn Euch, im Glauben, Ihr würdet sein Geheimnis ergründen.\"\n<Zum Lesen rechtsklicken>" }
entries[206034] = { ["name"] = "Zischender Runenentwurf", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Inschriftenkundewissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Inschriftenkunde der Dracheninseln (25)\n\"Ein leises Zischen erfüllt Euren Verstand. Sind es die Felsvipern in der Nähe oder die Rune?\"" }
entries[206035] = { ["name"] = "Uralte Forschung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Inschriftenkundewissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Inschriftenkunde der Dracheninseln (25)\n\"Überraschend gut erhaltener Text, der die Forschung an verschiedenen Runen und Magiearten beschreibt.\"" }
entries[206037] = { ["name"] = "Rubin-Flugstein", ["text"] = "Wird beim Aufheben gebunden\n\"Einst enthielt er die Macht der Flugsteine. Jetzt ist es ein schöner Briefbeschwerer.\"\nVerkaufspreis:" }
entries[206038] = { ["name"] = "Flammender Ring der Protzigkeit", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Zeigt ein protziges Spektakel mit einem explosiven Finale. (1 Stunde Abklingzeit)\n\"Feuer beeindruckt die Menge immer wieder.\"" }
entries[206039] = { ["name"] = "Feindseligkeitsbündel", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses Objekt verströmt Wellen des Hasses.\"\n<Zum Öffnen rechtsklicken>" }
entries[206040] = { ["name"] = "Partikel von Nasz'uro", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[206043] = { ["name"] = "Fyrakks Raserei", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört die Essenz von Fyrakk, um einen tiefen Atemzug zu entfesseln, der die in den Flammen gefangenen Kleintiere vernichtet. (10 Min Abklingzeit)" }
entries[206044] = { ["name"] = "Axt des Obsidiangladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Axt\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 30 / 30\nErlangt den Rang Elite in Saison 2 von Dragonflight.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206046] = { ["name"] = "Leerenberührte Kuriosität", ["text"] = "Wird beim Aufheben gebunden\n\"Ein faszinierendes und bedrohliches Omen. Kaitalla an der Obsidianrast in der Zaralekhöhle könnte vielleicht wissen, wie man seine verborgenen Geheimnisse entschlüsselt.\"\nVerkaufspreis:" }
entries[206134] = { ["name"] = "Trank der Heilung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (4)" }
entries[206135] = { ["name"] = "Trophäentruhe des heroischen Dungeongräbers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n<Zum Öffnen rechtsklicken>" }
entries[206136] = { ["name"] = "Trophäenwappen des heroischen Dungeongräbers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Enthält fünfzehn Schattenflammenwappenbruchstücke des Drachen.\"\n<Zum Öffnen rechtsklicken>" }
entries[206137] = { ["name"] = "Dolch des Obsidiangladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Dolch\n1 Schaden Geschwindigkeit 1.80\n(0.6 Schaden pro Sekunde)\nErlangt den Rang Elite in Saison 2 von Dragonflight.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206138] = { ["name"] = "Wimpel des Schuppenwächters", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Repräsentiert Eure Siege mit einem Banner. (2 Min Abklingzeit)\n\"Eure tapferen Taten erfüllen Eure Fraktion mit Stolz!\"" }
entries[206139] = { ["name"] = "Flüchtige blutrote Glut", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erfüllt Euch mit blutroter Macht und erhöht Euren verursachten Schaden um 30%, verletzt Euch aber auch mit Feuer, wodurch Ihr 24 Sek. lang alle 3 Sek. Feuerschaden in Höhe von 1% Eurer maximalen Gesundheit erleidet." }
entries[206140] = { ["name"] = "Beruhigender smaragdgrüner Tee", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erfüllt Euch mit smaragdgrüner Macht und heilt Euch um 25% Gesundheit sowie im Verlauf von 15 Sek. um 40% Eurer maximalen Gesundheit." }
entries[206141] = { ["name"] = "Prismatischer Schneckenschleim", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erfüllt Euch mit prismatischer Macht und erhöht Eure kritische Trefferchance 15 Sek. lang um 30%." }
entries[206142] = { ["name"] = "Sandiger Steintrank", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erfüllt Euch mit der Macht des Steins, erhöht Eure Rüstung um 300%, aber verringert auch Eure Bewegungsgeschwindigkeit um 15%." }
entries[206143] = { ["name"] = "Energiegeladene Temporalsporen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erfüllt Euch mit temporaler Macht und borgt 10% Eurer maximalen Gesundheit, um Eure Bewegungsgeschwindigkeit um 30% zu erhöhen." }
entries[206144] = { ["name"] = "Merkwürdiger Urzeitpilz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erfüllt Euch mit urzeitlicher Macht, verringert Euren erlittenen Magieschaden um 30%, schrumpft Euch aber auch und verringert Eure Bewegungsgeschwindigkeit um 20%.\n\"Ein Teil lässt Euch schrumpfen, der andere Teil allerdings auch.\"" }
entries[206145] = { ["name"] = "Geheimnisvolles Zeitrelikt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Was hat Chronolord Deios damit gemacht?\"" }
entries[206146] = { ["name"] = "Kriegsgleve des Obsidiangladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Kriegsgleve\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 35 / 35\nErlangt den Rang Elite in Saison 2 von Dragonflight.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206147] = { ["name"] = "Stangenwaffe des Obsidiangladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stangenwaffe\n1 - 3 Schaden Geschwindigkeit 3.60\n(0.6 Schaden pro Sekunde)\nHaltbarkeit 35 / 35\nErlangt den Rang Elite in Saison 2 von Dragonflight.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206148] = { ["name"] = "Stab des Obsidiangladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stab\n1 - 2 Schaden Geschwindigkeit 3.60\n(0.4 Schaden pro Sekunde)\nErlangt den Rang Elite in Saison 2 von Dragonflight.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206149] = { ["name"] = "Gewehr des Obsidiangladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz Schusswaffe\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\nHaltbarkeit 35 / 35\nErlangt den Rang Elite in Saison 2 von Dragonflight.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206150] = { ["name"] = "Streitkolben des Obsidiangladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Streitkolben\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 30 / 30\nErlangt den Rang Elite in Saison 2 von Dragonflight.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206151] = { ["name"] = "Rute des Obsidiangladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nIn Schildhand geführt\nErlangt den Rang Elite in Saison 2 von Dragonflight.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206152] = { ["name"] = "Schild des Obsidiangladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nSchildhand Schild\n14 Rüstung\nHaltbarkeit 35 / 35\nErlangt den Rang Elite in Saison 2 von Dragonflight.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206153] = { ["name"] = "Klauen des Obsidiangladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Faustwaffe\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nHaltbarkeit 25 / 25\nErlangt den Rang Elite in Saison 2 von Dragonflight.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206154] = { ["name"] = "Bogen des Obsidiangladiators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz Bogen\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\nHaltbarkeit 35 / 35\nErlangt den Rang Elite in Saison 2 von Dragonflight.\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206156] = { ["name"] = "Grottendrache der Netherschwingen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBeschwört einen reitbaren Grottendrachen der Netherschwingen oder gibt ihn wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\"Lehrt Euch, wie man dieses Reittier beschwört.\"\nVerkaufspreis:\n\"Nach ihrer Reise in die Scherbenwelt ist es ganz natürlich, dass diese Drachen nach neuen Himmeln suchen.\"\nQuest:\nDrachenhaltung\nZone:\nDer Smaragdgrüne Traum" }
entries[206158] = { ["name"] = "Schlüsselsteinaffix hinzufügen: Abschirmend", ["text"] = "Dauer: 12 std. (Realzeit)\nBenutzen: Fügt einem mythischen Schlüsselstein das Affix Abschirmend hinzu.\nVerkaufspreis:" }
entries[206160] = { ["name"] = "Madame Schattens Grimoire", ["text"] = "Questgegenstand\nBenutzen: Ruft die Macht von Madame Schattens Teufelsseelenstein an. (12 Sek. Abklingzeit)\n\"Ein feuchter und muffiger Foliant. Er riecht ein bisschen nach... Schwefel?\"" }
entries[206161] = { ["name"] = "Zeitversetztes Spielzeug", ["text"] = "Questgegenstand\n\"Ein geliebtes Quietschspielzeug, das in die falsche Zeit verlegt wurde.\"" }
entries[206162] = { ["name"] = "Flüchtiges Echo von Tarecgosa", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man sich ohne Drachenzorn in Tarecgosas Abbild verwandelt.\nVerwandelt Euch in Tarecgosas Abbild, wodurch Ihr erhöhte Bewegungsgeschwindigkeit erhaltet und fliegen könnt.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Lebt wohl, Tarecgosa. Geliebte Schwester, Heldin, Schülerin und Lehrerin. Auch ohne Blutsbande werdet Ihr immer Familie für mich sein. Möge Eure Seele ihren Platz unter den Sternen finden.\"\nQuest:\nRhapsodie in Blau" }
entries[206163] = { ["name"] = "Temporalgespinst", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\nVerkaufspreis:" }
entries[206164] = { ["name"] = "Schwaches Resonanzvestigium", ["text"] = "Questgegenstand" }
entries[206165] = { ["name"] = "Erhebliches Resonanzvestigium", ["text"] = "Questgegenstand" }
entries[206166] = { ["name"] = "Starkes Resonanzvestigium", ["text"] = "Questgegenstand" }
entries[206167] = { ["name"] = "Weg des wunderbaren Wellenschnauzers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Es heißt, einer dieser magischen Fische werde geboren, wenn ein Fischer von einem entkommenen Fang träumt... und mit jeder Erzählung der Geschichte wächst der magische Fisch.\"\nWoW-Shop" }
entries[206171] = { ["name"] = "Vol'jins Mojo", ["text"] = "Questgegenstand\n\"Das Mojo ist unter Kontrolle... vorläufig.\"" }
entries[206174] = { ["name"] = "Blubb", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
