entries[206195] = { ["name"] = "Pfad der Naaru", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt Euch zurück zu Eurem Heimatort: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\"Schlagt den Pfad der Wenigen ein.\"" }
