entries[206200] = { ["name"] = "Truhe mit Obsidianausrüstung", ["text"] = "Saison 2 von Dragonflight\nWird an Kriegsmeute gebunden\nBenutzen: Erschafft ein Ausrüstungsteil des Obsidiangladiators mit dem Rang 'Ungewertet', das für Eure Beutespezialisierung nützlich ist.\nErfordert eine PvP-Wertung von: 1.400 (beliebige Sparte)." }
entries[206203] = { ["name"] = "Trunk der Furchtloser Funke", ["text"] = "Questgegenstand\nEinzigartig (10)\n\"Dieses Getränk soll einem in dunklen Zeiten Mut verleihen.\"" }
entries[206204] = { ["name"] = "Geborgenes Relikt der Tuskarr", ["text"] = "Questgegenstand\n\"Ein Relikt, das zurückgelassen wurde, als die Gnolle die Tuskarr vertrieben haben.\"" }
entries[206205] = { ["name"] = "Stofftracht des Schuppenwächters", ["text"] = "Wird beim Aufheben gebunden\nBrust Stoff\n219 Rüstung\n+257 Intelligenz\n+416 Ausdauer\nErhöht Eure kritische Trefferwertung um + 208.\n+ 270 Vielseitigkeit\nHaltbarkeit 165 / 165\nBekleidung des Schuppenwächters (0/8)\nStoffmantel des Schuppenwächters\nStoffbindungen des Schuppenwächters\nStoffkordel des Schuppenwächters\nStoffhose des Schuppenwächters\nKrone des Schuppenwächters\nStoffhandschuhe des Schuppenwächters\nStoffpantoffeln des Schuppenwächters\nStofftracht des Schuppenwächters\n(2) Set : Erhöht die Vielseitigkeit um 56 .\n(4) Set : Wenn Ihr betäubt seid, steigt Eure Entschlossenheit und Ihr absorbiert 10 Sek. lang bis zu [ 23631 * (1 + Vielseitigkeit)] Schaden. Dieser Effekt kann nur einmal alle 2 Min. auftreten.\n(6) Set : Das Töten von gegnerischen Spielercharakteren gewährt 'Raserei des Brechers', was die Vielseitigkeit um 2% und die Bewegungsgeschwindigkeit um 2% erhöht. Bis zu 10-mal stapelbar.\nVerkaufspreis:" }
