entries[206343] = { ["name"] = "Standarte der blutroten Legende", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Repräsentiert Euren Saisonerfolg mit einem Banner. (2 Min Abklingzeit)" }
entries[206346] = { ["name"] = "Evas Tagebuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Führt ein Ritual durch.\n\"Eine detaillierte Auflistung von immer schrecklicheren Ereignissen. Viele Seiten sind leer.\"" }
entries[206347] = { ["name"] = "Kleiderpuppenzauber", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Verwandelt den Zaubernden in eine Kleiderpuppe aus dem Handelsposten. (10 Min Abklingzeit)\n\"Repräsentiert den Handelsposten.\"\nVerkaufspreis:" }
entries[206348] = { ["name"] = "Fragmentierte Flamme", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Vereint 5 Flammenfragmente, um ein fragmentiertes Reagenz oder einen Flammensplitter zu erschaffen.\n\"Die zerschmetterten Reste eines Flammensplitters, der bei einem der letzten Angriffe geraubt wurde.\"\nVerkaufspreis:" }
entries[206349] = { ["name"] = "Fragmentiertes Reagenz", ["text"] = "Questgegenstand\nEinzigartig\n\"Vereinigt fragmentierte Flammen, um etwas ganz Neues zu erschaffen!\"" }
entries[206350] = { ["name"] = "Strahlendes Überbleibsel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ruhmrang 23 bei den Arathi von Heilsturz.\nBenötigt Ruhmrang 25 bei den Arathi von Heilsturz.\n\"Ein wertvolles Reagenz, mit dem das Licht der Schlüsselflammen gespeist wird.\"" }
entries[206351] = { ["name"] = "Pläne: Echtsilberchampion", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man den einen Echtsilberchampion herstellt.\nBenötigt Klassische Schmiedekunst (300)\nVerkaufspreis:\nEchtsilberchampion\nWird beim Anlegen gebunden\nZweihändig Schwert\n6 - 11 Schaden Geschwindigkeit 3.60\n(2.4 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\nTrefferchance: Beschützt den Zaubernden mit einem heiligen Schild.\nVerkaufspreis:\nBenötigt Mithrilbarren (30), Echtsilberbarren (16), Sternrubin (6), Odem des Windes (4), Robuster Schleifstein (8), Dickes Leder (6)\nOptionale Reagenzien: [] (#49)" }
entries[206352] = { ["name"] = "Pläne: Der Zertrümmerer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man den Zerschmetterer herstellt.\nBenötigt Klassische Schmiedekunst (300)\nVerkaufspreis:\nDer Zertrümmerer\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n4 - 5 Schaden Geschwindigkeit 2.60\n(1.7 Schaden pro Sekunde)\n+2 Stärke\n+2 Ausdauer\nHaltbarkeit 90 / 90\nVerkaufspreis:\nBenötigt Mithrilbarren (24), Erdenkern (4), Echtsilberbarren (6), Citrin (5), Jade (5), Robuster Schleifstein (4), Dickes Leder (4)\nOptionale Reagenzien: [] (#31)" }
entries[206353] = { ["name"] = "Pfeife der Schildwache", ["text"] = "Questgegenstand\nBenutzen: Beschwört einen Hippogryphen, um schnell von Lunedane nach Valdrakken zu fliegen.\n\"Eine kleinen Runenholzpfeife, die einen schrillen, trillernden Ton erzeugt.\"" }
entries[206354] = { ["name"] = "Stinkende Kerze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Perfekt für Tage, an denen man sich wünscht, dass alle einen in Ruhe lassen.\"" }
entries[206355] = { ["name"] = "Tabakgefüllte Kerze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Wenn der Kurier zu spät kommt, muss man die Dinge manchmal selbst in die Hand nehmen.\"" }
entries[206356] = { ["name"] = "Geisterschutzkerze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Soll angeblich die Geister fernhalten, aber das ist bestimmt nur eine Kindergeschichte.\"" }
entries[206357] = { ["name"] = "Authentische Kerze aus Andorhal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine Kerze, die so gewöhnlich ist, dass sie schon wieder verdächtig ist.\"" }
entries[206358] = { ["name"] = "Importierte Kerze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Das bemerkenswerteste Detail an dieser Kerze ist, dass jemand es geschafft hat, \"Corins Kreuzung\" in den Boden zu ritzen.\"" }
entries[206359] = { ["name"] = "Brunnenwasser aus Darrowehr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Viel zu zähflüssig, um zu verdampfen.\"" }
entries[206360] = { ["name"] = "Nicht zugestellte Rauchwarenlieferung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine Kiste mit den besten Zigarren, die Ezra Grimm zu bieten hatte.\"" }
entries[206361] = { ["name"] = "Zertrampelte Puppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Auf dem zerknitterten Zettel in einer der Taschen der Puppe steht: \"Für meine beste Freundin, von Pamela\".\"" }
entries[206362] = { ["name"] = "Die Besitzurkunde für Andorhal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Trägt ein verblasstes Siegel.\"" }
entries[206363] = { ["name"] = "Der Weg hinaus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Eine wunderschöne Zeichnung der Straße, die von Corins Kreuzung wegführt. Die Signatur \"Renfray\" ist sorgfältig in einer Ecke platziert.\"" }
entries[206364] = { ["name"] = "Evas Oberschenkelknochen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Wahrscheinlich nicht das, was Eva von Euch für das Ritual erwartet hat, aber es erfüllt seinen Zweck.\"" }
entries[206365] = { ["name"] = "Inaktive spektrale Essenz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Mit 5 Essenzen des Untodes und 3 Dunkelrunen erfüllen.\n\"Ermöglicht die Kommunikation mit den vor langer Zeit Verstorbenen von Darrowehr.\"" }
entries[206366] = { ["name"] = "Gesprungene Trophäe der Zwietracht", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[206367] = { ["name"] = "Gesprungene Trophäe der Zwietracht", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[206368] = { ["name"] = "Zauberstab der Massenverwandlung", ["text"] = "Questgegenstand\n\"Ein mit 'Verwandlung' aufgeladener Zauberstab, um Ziele in Schafe zu verwandeln.\"" }
entries[206369] = { ["name"] = "Zeitfalle", ["text"] = "Questgegenstand\nBenutzen: Fängt Chromie aus einer alternativen Zeitlinie vorübergehend in Stasis ein, um ihre Zeitsignatur zu synchronisieren. (3 Sek. Abklingzeit)\n\"Aufbewahrt in einem sich endlos drehenden Möbiusbandelier.\"" }
entries[206370] = { ["name"] = "Blut der Unschuldigen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Das Blut ist immer noch frisch.\"" }
entries[206371] = { ["name"] = "Schlüssel zum Vorführraum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[206372] = { ["name"] = "Gesprungene Anstecknadel der Argentumdämmerung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Repariert das Insigne mit einer rechtschaffenen Kugel und 4 Echtsilberbarren.\n\"Dieses Abzeichen war einst ein Zeichen des Dienstes für die Argentumdämmerung.\"" }
entries[206373] = { ["name"] = "Geißelstein des Dunkelmeisters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest." }
entries[206374] = { ["name"] = "Geißelstein des Eindringlings", ["text"] = "Wird an Kriegsmeute gebunden" }
entries[206375] = { ["name"] = "Geißelstein des Verderbers", ["text"] = "Wird an Kriegsmeute gebunden" }
entries[206377] = { ["name"] = "Schutz von Naxxramas", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Durchbricht den Schutz." }
entries[206393] = { ["name"] = "Muster: Gletscherumhang", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Gletscherumhang näht.\nBenötigt Klassische Schneiderei (300)\nVerkaufspreis:\nGletscherumhang\nWird beim Anlegen gebunden\nRücken\n3 Rüstung\n+3 Ausdauer\n+2 Frostwiderstand\nVerkaufspreis:\nBenötigt Gefrorene Rune (5), Runenstoffballen (4), Essenz des Wassers (2), Eisenweberseide (4)\nOptionale Reagenzien: [] (#31)" }
entries[206394] = { ["name"] = "Rotdrachenei", ["text"] = "Questgegenstand\n\"Die Schale dieses Eis fühlt sich warm, aber fest an. Es dauert noch eine Weile, bis es schlüpfen wird.\"" }
