entries[206474] = { ["name"] = "Stinkender Käse", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. ( 42188 / 5 * 20) Gesundheit wieder her.\nIhr müsst beim Essen sitzen bleiben.\n\"Der Geruch, den dieser Käse verströmt, verrät Euch, dass es entweder ein sehr guter Käse ist... oder ein wirklich schlechter Käse.\"" }
entries[206475] = { ["name"] = "Parakausales Fragment des Seschenal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+396 Intelligenz\nAnlegen: Eure Heilung hat eine geringe Chance, in der Nähe Eures Zielortes einen Schössling des Lebens zu manifestieren, der 15 Sek. lang regelmäßig 11438 Gesundheit aufgeteilt auf Euch und alle Verbündete in Eurer Gruppe wiederherstellt und dabei langsam verschwindet. Den Schössling des Lebens zu heilen, verlängert seine Dauer auf bis zu 30 Sek..\nVerkaufspreis:" }
