entries[206555] = { ["name"] = "Uralte Pläne: Stulpen des Unerbittlichen", ["text"] = "Benutzen: Lehrt Euch, wie man Stulpen des Unerbittlichen herstellt.\nBenötigt Klassische Schmiedekunst (300)\nVerkaufspreis:\nStulpen des Unerbittlichen\nWird beim Anlegen gebunden\nHände Platte\n8 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 55 / 55\nAnlegen: Die Wirkungsdauer von 'Entwaffnen' wird um 50% verringert.\nVerkaufspreis:\nBenötigt Kampfzerrissene Fetzen (35), Blut der Unschuldigen , Stahlwaffenkette (2), Sternrubin (4), Arkanitbarren (8), Dunkelrune (2)" }
