entries[206557] = { ["name"] = "Uralte Pläne: Todesspiel", ["text"] = "Benutzen: Lehrt Euch, wie man Todesspiel herstellt.\nBenötigt Klassische Schmiedekunst (300)\nVerkaufspreis:\nTodesspiel\nWird beim Anlegen gebunden\nSchildhand Schild\n42 Rüstung\n+2 Stärke\n+6 Intelligenz\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\n+ 2 Vielseitigkeit\nHaltbarkeit 120 / 120\nVerkaufspreis:\nBenötigt Kampfzerrissene Fetzen (60), Essenz des Untodes (40), Gewaltiger Smaragd (20), Geisterfarbstoff (60), Arkanitbarren (12)" }
entries[206558] = { ["name"] = "Uralte Pläne: Gürtel des Mentors", ["text"] = "Benutzen: Lehrt Euch, wie man einen Gürtel des Mentors herstellt.\nBenötigt Klassische Schmiedekunst (300)\nVerkaufspreis:\nGürtel des Mentors\nWird beim Anlegen gebunden\nTaille Platte\n8 Rüstung\n+2 [Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 55 / 55\nVerkaufspreis:\nBenötigt Kampfzerrissene Fetzen (15), Echtsilberbarren (45), Arkanitbarren (8), Azerothischer Diamant (4), Essenz des Untodes (30)" }
entries[206559] = { ["name"] = "Uralter Bauplan: Servoersatzarm", ["text"] = "Benutzen: Lehrt Euch, wie man einen Servoersatzarm herstellt.\nBenötigt Klassische Ingenieurskunst (300)\nVerkaufspreis:\nServoersatzarm\nWird beim Anlegen gebunden\nEinhändig Streitkolben\n4 - 6 Schaden Geschwindigkeit 2.60\n(1.9 Schaden pro Sekunde)\nHaltbarkeit 110 / 110\nAnlegen: Es besteht eine Chance, dass eine elektrische Entladung ausgelöst wird, die Eurem Ziel 2 Naturschaden hinzufügt.\nVerkaufspreis:\nBenötigt Kampfzerrissene Fetzen (40), Essenz des Untodes (20), Empfindlicher Arkanitwandler (12), Instabiler Auslöser (20), Gyrochronatom (16), Verschmorte Verkabelung (200)" }
entries[206560] = { ["name"] = "Uralte Pläne: Stygischer Schild", ["text"] = "Benutzen: Lehrt Euch, wie man einen stygischen Schild herstellt.\nBenötigt Klassische Schmiedekunst (300)\nVerkaufspreis:\nStygischer Schild\nWird beim Anlegen gebunden\nSchildhand Schild\n42 Rüstung\n+2 Stärke\n+6 Intelligenz\n+3 Ausdauer\nHaltbarkeit 120 / 120\nAnlegen: Bei einem Treffer besteht eine Chance von 15%, dass die Bewegungsgeschwindigkeit des Angreifers 5 Sek. lang um 50% verringert wird. Es besteht die Chance, dass der Effekt gegen Ziele über Stufe 49 nicht wirkt. (Procchance: 15%)\nVerkaufspreis:\nBenötigt Kampfzerrissene Fetzen (60), Goldbarren (20), Arkanitbarren (6), Geisterfarbstoff (16), Großer Opal (20)" }
entries[206561] = { ["name"] = "Uraltes Muster: Luciens verlorene Sohlen", ["text"] = "Benutzen: Lehrt Euch, wie man Luciens verlorene Sohlen herstellt.\nBenötigt Klassische Lederverarbeitung (300)\nVerkaufspreis:\nLuciens verlorene Sohlen\nWird beim Anlegen gebunden\nFüße Leder\n4 Rüstung\n+2 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 3.\nHaltbarkeit 60 / 60\nVerkaufspreis:\nBenötigt Unverwüstliches Leder (16), Geschmeidiger unverwüstlicher Balg (4), Essenz des Untodes (6), Runenfaden (6)" }
entries[206562] = { ["name"] = "Tuch der verbotenen Magie", ["text"] = "Kosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[206563] = { ["name"] = "Uraltes Muster: Tuch der verbotenen Magie", ["text"] = "Benutzen: Lehrt Euch, wie man ein Tuch der verbotenen Magie herstellt.\nBenötigt Klassische Schneiderei (300)\n\nTuch der verbotenen Magie\nKosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:\nBenötigt Kampfzerrissene Fetzen (200), Essenz des Untodes (100), Teufelsstoff (50), Großer glänzender Splitter (60), Dunkelrune (25), Geisterfarbstoff (20)" }
entries[206564] = { ["name"] = "Zeitverschobene Titanenscheibe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Dieser Gegenstand ist eindeutig titanischen Ursprungs. Trotz des Speichels, der davon herabtropft, scheint die Scheibe immer noch funktionsfähig zu sein.\"" }
entries[206565] = { ["name"] = "Verseuchtes Korn", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert für 3 Min. eine Kiste mit ganz gewöhnlichem Korn. Niemand wird sich etwas dabei denken. (2 Std. Abklingzeit)\n\"Eine an die Kapelle des Hoffnungsvollen Lichts adressierte Kiste. Zum Glück kam sie nie dort an.\"" }
entries[206566] = { ["name"] = "Zügel des scharlachroten Pterrordax", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen scharlachroten Pterrordax beschwört.\nBeschwört Euren scharlachroten Pterrordax oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser Pterrordax war so eifrig darauf, sich in die Lüfte zu schwingen, dass sein Trainer die Ausbildung nicht beenden konnte.\"\nQuest:\nZeit zum Fliegen" }
entries[206567] = { ["name"] = "Hafengreif", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man einen Hafengreifen beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser Greif war der kleinste seines Rudels und wurde zurückgelassen, als seine Geschwister in die Ausbildung geschickt wurden. Heute ist er jedoch bereit, sich zu beweisen.\"\nQuest:\nZeit zum Fliegen" }
