entries[206576] = { ["name"] = "Druckmittel des Todes", ["text"] = "Wird an Kriegsmeute gebunden" }
entries[206577] = { ["name"] = "Schleimbedeckte Schriftrolle", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Enthüllt ein zufälliges uraltes Rezept aus Naxxramas.\n\"Es gibt kein Geld zurück.\"" }
entries[206578] = { ["name"] = "Ein Schädel mit Geweih", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Trotz der Zeitlinie, aus der er stammt, ist dieser Schädel unerklärlicherweise frei von Teufelsenergie. Ihr spürt eine seltsame Ruhe, wenn Ihr ihn haltet.\"" }
entries[206579] = { ["name"] = "Phylaktergewebe", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (1400)\nHandwerksmaterial\n\"Seine seelenabsorbierenden Eigenschaften machen es zu einer essentiellen Komponente bei der Läuterung entweihter Gegenstände.\"" }
entries[206581] = { ["name"] = "Ernterkern", ["text"] = "Wird beim Aufheben gebunden" }
entries[206582] = { ["name"] = "Eigenartiger Gletschermantel", ["text"] = "Wird beim Anlegen gebunden\nSchulter Stoff\n3 Rüstung\n+2 Intelligenz\n+4 Ausdauer\n+3 Frostwiderstand\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[206583] = { ["name"] = "Uraltes Muster: Eigenartiger Gletschermantel", ["text"] = "Benutzen: Lehrt Euch, wie man einen eigenartigen Gletschermantel herstellt.\nBenötigt Klassische Schneiderei (300)\nVerkaufspreis:\nEigenartiger Gletschermantel\nWird beim Anlegen gebunden\nSchulter Stoff\n3 Rüstung\n+2 Intelligenz\n+4 Ausdauer\n+3 Frostwiderstand\nHaltbarkeit 100 / 100\nVerkaufspreis:\nBenötigt Gefrorene Rune (10), Runenstoffballen (12), Essenz des Wassers (9), Eisenweberseide (12)" }
entries[206584] = { ["name"] = "Archivierte Handwerkstechniken", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Enthüllt ein zufälliges uraltes Rezept aus Lordaeron oder den umliegenden Regionen." }
entries[206585] = { ["name"] = "Zügel von Tapferkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man Tapferkeit beschwört.\nBeschwört Tapferkeit oder gibt das Ross wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Für die meisten untoten Rösser wird der Reiter ausgewählt. Tapferkeit jedoch wählt seine Reiter selbst.\"\nEntdeckung:\nTapferkeit\nOrt:\nNaxxramas" }
entries[206586] = { ["name"] = "Epochenextraktor", ["text"] = "Questgegenstand\nBenutzen: Entzieht besiegten zeitverlorenen Kreaturen innerhalb von 15 Metern zeitverlorene Essenz. (3 Sek. Abklingzeit)\n\"Ein Gerät, mit dem Ihr die Essenz zeitverlorener Kreaturen stehlen könnt.\"" }
