entries[206596] = { ["name"] = "Foliant von Thomas Thomson", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein abgegriffener Foliant, dessen Einband der Name \"Thomson\" ziert.\"\n<Zum Lesen rechtsklicken>" }
entries[206598] = { ["name"] = "Schwelende Blüte", ["text"] = "Questgegenstand\n\"Ewig brennend, doch unfähig zu sterben. Die Aspekte werden das sehen wollen.\"" }
entries[206599] = { ["name"] = "Azmerlothianisches Stundenglas", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Der Sand dieses Stundenglases scheint an Ort und Stelle in der Zeit gefangen zu schweben. Die Symbolik, mit der sie verziert ist, ist fast identisch mit den Euch bekannten Stundengläsern des Bronzenen Drachenschwarms, nur mit mehr Murlocs.\"" }
entries[206600] = { ["name"] = "Ein Hinweis", ["text"] = "Geheimnisse von Azeroth\nEinzigartig\nDauer: 22 std.\n\"BANK\"" }
entries[206601] = { ["name"] = "Dunkelheitsgenährte Frühlingszwiebeln", ["text"] = "Questgegenstand" }
entries[206602] = { ["name"] = "Mechanisiertes Zahnrad", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Dieses Zahnrad scheint ein Stück vor und zurück zu schwirren, obwohl es nicht mehr Teil eines Mechanismus ist. In die Seite ist ein Schriftzug geätzt: \"Mechanisierung ist der einzige Weg zu wahrem Frieden.\"\"" }
entries[206604] = { ["name"] = "Helm des beklagten Kreuzfahrers", ["text"] = "\"Alles, was von der epischen Ausrüstung eines mächtigen Champions übrig geblieben ist. Vielleicht kann man den alten Glanz wieder aufleben lassen.\"\nVerkaufspreis:" }
