entries[206612] = { ["name"] = "Entweihter Tuchhelm", ["text"] = "Wird an Kriegsmeute gebunden\nKlassen: Priester , Magier , Hexenmeister\nBenutzen: Läutert den Helm mit 280 Stück Phylaktergewebe und 10 rechtschaffenen Kugeln, um einen sehr begehrten Helm für Eure Klasse zu erhalten.\n\"Ein Ausrüstungsteil, das mithilfe einer unheiligen Beschwörungsformel mit verbotener Kraft versehen wurde.\"" }
