entries[206638] = { ["name"] = "Azeleids verderbter Aschenbringer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"In ihrem Zeitweg wurde die Waffe nie von der Verderbnis befreit. Berührt sie besser nicht ungeschützt.\"" }
