entries[206645] = { ["name"] = "Verfluchter Stoff", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\nDer so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Magier, Priester oder Hexenmeister geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen.\nVerkaufspreis:" }
entries[206646] = { ["name"] = "Ermattetes Leder", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Repariert ein Ausrüstungsteil des beklagten Kreuzfahrers mit verderbten Materialien und stellt so einen Teil seiner früheren Pracht wieder her.\n\nDer so entstandene Gegenstand wird kriegsmeutengebunden und die Entweihung kann von einem Druiden oder Schurken geläutert werden, der gewillt ist, die nötigen Reagenzien zu beschaffen.\nVerkaufspreis:" }
